function canAccess(){if(!state.perfil)return false;if(state.perfil.tipo==='admin')return true;if(!Array.isArray(state.perfil.permissoes))return true;return state.perfil.permissoes.includes('treinamentos')}
async function loadProfile(user){state.user=user||null;state.perfil=null;if(!user)return;const snap=await getDoc(doc(db,'usuarios',user.uid));state.perfil=snap.exists()?{id:snap.id,...snap.data()}:null}
async function loadCompanies(){if(state.perfil?.tipo==='admin'){const s=await getDocs(collection(db,'empresas'));state.empresas=s.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR'))}else{const id=state.perfil?.empresaId||'';if(!id){state.empresas=[];return}const s=await getDoc(doc(db,'empresas',id));state.empresas=s.exists()?[{id:s.id,...s.data()}]:[]}}
function mainEl(){return document.querySelector('.main')}
function clearCache(){state.cache=null;state.cacheAt=0}
function ensureMenu(){if(!state.perfil||!canAccess())return;const nav=document.querySelector('#sidebar .nav-group,.sidebar .nav-group,#sidebar nav,.sidebar nav');if(!nav)return;let btn=[...nav.querySelectorAll('.nav-btn')].find(b=>norm(text(b)).includes('treinamento'));if(!btn){btn=document.createElement('button');btn.type='button';btn.className='nav-btn';btn.innerHTML='<span>▤</span>Treinamentos';const apont=[...nav.querySelectorAll('.nav-btn')].find(b=>norm(text(b)).includes('apontamento'));const quem=[...nav.querySelectorAll('.nav-btn')].find(b=>norm(text(b)).includes('quem somos'));if(apont?.parentElement===nav)apont.insertAdjacentElement('afterend',btn);else if(quem?.parentElement===nav)nav.insertBefore(btn,quem);else nav.appendChild(btn)}btn.style.display='';if(btn.dataset.trainingRootBound==='1')return;btn.dataset.trainingRootBound='1';btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();openTraining()},true)}
function rememberCompany(id,name=''){state.empresaId=id||'';state.empresaNome=name||'';try{if(id)sessionStorage.setItem(COMPANY_SESSION,id);else sessionStorage.removeItem(COMPANY_SESSION)}catch(_){}}
async function qCompany(name){const s=await getDocs(query(collection(db,name),where('empresaId','==',state.empresaId)));return s.docs.map(d=>({id:d.id,...d.data()}))}
async function loadData(force=false){if(!state.empresaId)return null;if(!force&&state.cache&&Date.now()-state.cacheAt<8000)return state.cache;const [plans,cols,matrix,events,pids,integrations,careers]=await Promise.all([qCompany('empresa_treinamentos'),qCompany('empresa_colaboradores'),qCompany('empresa_matriz_competencias'),qCompany('empresa_treinamento_eventos'),qCompany('empresa_pids'),qCompany('empresa_integracoes'),qCompany('empresa_carreiras')]);plans.sort((a,b)=>String(a.dataPrevista||'').localeCompare(String(b.dataPrevista||'')));cols.sort((a,b)=>String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR'));events.sort((a,b)=>String(b.data||'').localeCompare(String(a.data||'')));state.cache={plans,cols,matrix,events,pids,integrations,careers};state.cacheAt=Date.now();return state.cache}
function applicableRows(d){return d.matrix.filter(m=>m.aplicavel!==false&&norm(m.status)!=='nao aplicavel')}
function planRows(plan,d){return applicableRows(d).filter(m=>m.treinamentoId===plan.id)}
function planStage(plan,d){const rows=planRows(plan,d);if(plan.publicoDefinido!==true||!rows.length)return{step:1,label:'Definir público',cls:'warn'};if(rows.some(r=>norm(r.status)!=='concluido'))return{step:2,label:'Realização',cls:'warn'};if(rows.some(r=>norm(r.eficaciaStatus)!=='eficaz'))return{step:3,label:'Eficácia',cls:'warn'};return{step:4,label:'Concluído',cls:'ok'}}
function badge(status=''){const n=norm(status);const cls=['concluido','eficaz','aprovado','ativo'].includes(n)?'ok':['reprovado','ineficaz','atrasado'].includes(n)?'bad':'warn';return `<span class="tr-badge ${cls}">${esc(status||'Pendente')}</span>`}
function dateBr(v){if(!v)return '-';if(v?.toDate)return v.toDate().toLocaleDateString('pt-BR');const d=new Date(String(v).length===10?`${v}T12:00:00`:v);return Number.isNaN(d.getTime())?String(v):d.toLocaleDateString('pt-BR')}
function initials(name=''){const p=String(name).trim().split(/\s+/).filter(Boolean);return((p[0]?.[0]||'')+(p.length>1?(p.at(-1)?.[0]||''):'')).toUpperCase()||'•'}
function modal(title,subtitle,body){document.querySelector('.tr-modal-bg')?.remove();const bg=document.createElement('div');bg.className='tr-modal-bg';bg.innerHTML=`<div class="tr-modal"><div class="tr-modal-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="tr-btn soft" type="button" data-close>Fechar</button></div>${body}</div>`;document.body.appendChild(bg);bg.addEventListener('click',e=>{if(e.target===bg||e.target.closest('[data-close]'))bg.remove()});return bg}

async function openTraining(){if(!canAccess())return toast('Seu usuário não tem permissão para Treinamentos.','err');injectStyle();if(!state.empresas.length)await loadCompanies();if(state.perfil?.tipo!=='admin'){const e=state.empresas[0];if(!e)return toast('Nenhuma empresa vinculada ao usuário.','err');rememberCompany(e.id,e.nome||'Empresa');state.screen='trainings';state.activePlanId='';clearCache();return renderApp(true)}if(!state.empresaId){try{const stored=sessionStorage.getItem(COMPANY_SESSION)||'';const found=state.empresas.find(e=>e.id===stored);if(found)rememberCompany(found.id,found.nome||'Empresa')}catch(_){}}if(!state.empresaId)return renderCompanySelect();return renderApp(true)}
function renderCompanySelect(){const main=mainEl();if(!main)return;main.innerHTML=`<section class="tr-root"><div class="tr-hero"><div><small>GESTÃO DE PESSOAS</small><h1>Treinamentos</h1><p>Escolha a empresa para gerenciar cada treinamento de forma independente.</p></div></div><div class="tr-company-grid">${state.empresas.map(e=>`<article class="tr-company" data-company="${esc(e.id)}"><span class="tr-badge">Abrir</span><h3>${esc(e.nome||'Empresa')}</h3><p>${esc(e.cnpj||e.documento||'')}</p></article>`).join('')||'<div class="tr-empty">Nenhuma empresa cadastrada.</div>'}</div></section>`;main.querySelectorAll('[data-company]').forEach(card=>card.addEventListener('click',()=>{const e=state.empresas.find(x=>x.id===card.dataset.company);if(!e)return;rememberCompany(e.id,e.nome||'Empresa');state.screen='trainings';state.activePlanId='';clearCache();renderApp(true)}))}

async function renderApp(force=false){const main=mainEl();if(!main)return;const d=await loadData(force);if(!d)return;if(state.screen==='plan'&&state.activePlanId&&!d.plans.some(p=>p.id===state.activePlanId)){state.screen='trainings';state.activePlanId=''};main.innerHTML=`<section class="tr-root"><div class="tr-hero"><div><small>GESTÃO DE TREINAMENTOS</small><h1>${esc(state.empresaNome)}</h1><p>Cada treinamento possui seu próprio card e avança no próprio ritmo. Os relatórios ficam em uma área separada e podem ser gerados por treinamento ou de forma consolidada.</p></div><div class="tr-hero-actions">${state.perfil?.tipo==='admin'?'<button class="tr-btn soft" type="button" data-change-company>Trocar empresa</button>':''}</div></div><nav class="tr-main-nav"><button data-screen="trainings" class="${state.screen==='trainings'||state.screen==='plan'?'active':''}">Treinamentos</button><button data-screen="employees" class="${state.screen==='employees'?'active':''}">Funcionários</button><button data-screen="reports" class="${state.screen==='reports'?'active':''}">Relatórios</button><button data-screen="management" class="${state.screen==='management'?'active':''}">Gestão contínua</button></nav><div data-training-content></div></section>`;main.querySelector('[data-change-company]')?.addEventListener('click',()=>{rememberCompany('','');state.screen='trainings';state.activePlanId='';clearCache();renderCompanySelect()});main.querySelectorAll('[data-screen]').forEach(b=>b.addEventListener('click',()=>{state.screen=b.dataset.screen;state.activePlanId='';state.reportReady=false;renderApp()}));if(state.screen==='employees')return renderEmployees(d);if(state.screen==='reports')return renderReports(d);if(state.screen==='management')return renderManagement(d);if(state.screen==='plan')return renderPlan(d);return renderTrainings(d)}
function contentEl(){return document.querySelector('[data-training-content]')}

function renderTrainings(d){const root=contentEl();const stages=d.plans.map(p=>planStage(p,d));const finished=stages.filter(s=>s.step===4).length;root.innerHTML=`${d.plans.length&&!d.cols.length?`<div class="tr-alert info"><strong>Próximo passo:</strong> você já criou treinamento. Agora cadastre ou importe os funcionários para começar a definir os públicos. <button class="tr-btn soft" type="button" data-go-employees style="margin-left:8px">Abrir funcionários</button></div>`:''}<section class="tr-section"><div class="tr-section-head"><div><h2>Treinamentos</h2><p>Cada card é um processo independente. Um treinamento pendente não bloqueia os demais.</p></div><button class="tr-btn gold" type="button" data-new-training>Novo treinamento</button></div>${d.plans.length?`<div class="tr-summary" style="margin-bottom:14px"><div class="tr-kpi"><small>Total</small><strong>${d.plans.length}</strong></div><div class="tr-kpi"><small>Em andamento</small><strong>${d.plans.length-finished}</strong></div><div class="tr-kpi"><small>Concluídos</small><strong>${finished}</strong></div><div class="tr-kpi"><small>Funcionários</small><strong>${d.cols.length}</strong></div></div><div class="tr-grid">${d.plans.map(p=>trainingCard(p,d)).join('')}</div>`:`<div class="tr-empty"><strong>Nenhum treinamento cadastrado</strong>Crie o primeiro treinamento para iniciar o processo.</div>`}</section>`;root.querySelector('[data-new-training]')?.addEventListener('click',()=>showTrainingForm());root.querySelector('[data-go-employees]')?.addEventListener('click',()=>{state.screen='employees';renderApp()});root.querySelectorAll('[data-open-plan]').forEach(b=>b.addEventListener('click',()=>{state.activePlanId=b.dataset.openPlan;state.screen='plan';renderApp()}));root.querySelectorAll('[data-edit-plan]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();showTrainingForm(d.plans.find(p=>p.id===b.dataset.editPlan))}));root.querySelectorAll('[data-delete-plan]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();deleteTraining(b.dataset.deletePlan,d)}))}
function trainingCard(p,d){const st=planStage(p,d),rows=planRows(p,d),done=rows.filter(r=>norm(r.status)==='concluido').length,effective=rows.filter(r=>norm(r.eficaciaStatus)==='eficaz').length;return `<article class="tr-card tr-training-card s${st.step}"><div class="tr-training-top"><div><h3>${esc(p.titulo||'Treinamento')}</h3><p>${esc(p.objetivo||p.publicoAlvo||'')}</p></div><span class="tr-badge ${st.cls}">${esc(st.label)}</span></div><div class="tr-training-meta"><span class="tr-badge">Previsão: ${dateBr(p.dataPrevista)}</span>${p.cargaHoraria?`<span class="tr-badge">${esc(p.cargaHoraria)}</span>`:''}</div><div class="tr-progress">${[1,2,3,4].map(n=>`<span class="${n<st.step?'done':n===st.step?'current':''}"></span>`).join('')}</div><div class="tr-card-stats"><div class="tr-card-stat"><small>Público</small><strong>${rows.length}</strong></div><div class="tr-card-stat"><small>Realizados</small><strong>${done}</strong></div><div class="tr-card-stat"><small>Eficazes</small><strong>${effective}</strong></div></div><div class="tr-card-foot"><div><button class="tr-btn soft" data-edit-plan="${p.id}">Editar</button> <button class="tr-btn danger" data-delete-plan="${p.id}">Excluir</button></div><button class="tr-btn ${st.step===4?'ok':'primary'}" data-open-plan="${p.id}">${st.step===4?'Ver treinamento':'Continuar'}</button></div></article>`}

function showTrainingForm(item=null){const bg=modal(item?'Editar treinamento':'Novo treinamento',item?'Atualize os dados do treinamento.':'Cada treinamento terá seu próprio fluxo independente.',`<form class="tr-form" data-training-form><div><label>Título *</label><input name="titulo" required value="${esc(item?.titulo||'')}"></div><div><label>Data prevista</label><input type="date" name="dataPrevista" value="${esc(item?.dataPrevista||'')}"></div><div><label>Instrutor</label><input name="instrutor" value="${esc(item?.instrutor||'')}"></div><div><label>Carga horária</label><input name="cargaHoraria" placeholder="Ex.: 2h" value="${esc(item?.cargaHoraria||'')}"></div><div><label>Periodicidade</label><input name="periodicidade" value="${esc(item?.periodicidade||'')}"></div><div><label>Público planejado</label><input name="publicoAlvo" value="${esc(item?.publicoAlvo||'')}"></div><div class="full"><label>Objetivo</label><textarea name="objetivo">${esc(item?.objetivo||'')}</textarea></div><div class="full"><label>Evidência esperada</label><input name="evidenciaEsperada" value="${esc(item?.evidenciaEsperada||'')}"></div><div class="full"><button class="tr-btn primary" type="submit">${item?'Salvar alterações':'Salvar treinamento'}</button></div></form>`);bg.querySelector('[data-training-form]').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const data={empresaId:state.empresaId,titulo:f.get('titulo'),dataPrevista:f.get('dataPrevista')||'',instrutor:f.get('instrutor')||'',cargaHoraria:f.get('cargaHoraria')||'',periodicidade:f.get('periodicidade')||'',publicoAlvo:f.get('publicoAlvo')||'',objetivo:f.get('objetivo')||'',evidenciaEsperada:f.get('evidenciaEsperada')||'',atualizadoEm:serverTimestamp()};if(item)await updateDoc(doc(db,'empresa_treinamentos',item.id),data);else await addDoc(collection(db,'empresa_treinamentos'),{...data,status:'Planejado',publicoDefinido:false,criadoEm:serverTimestamp(),criadoPor:state.user?.uid||''});bg.remove();clearCache();toast(item?'Treinamento atualizado.':'Treinamento criado.');state.screen='trainings';renderApp(true)})}
async function deleteTraining(id,d){if(d.events.some(e=>e.treinamentoId===id))return toast('Este treinamento já possui realizações e não pode ser excluído.','err');if(!confirm('Excluir este treinamento?'))return;await deleteDoc(doc(db,'empresa_treinamentos',id));for(const m of d.matrix.filter(x=>x.treinamentoId===id))await deleteDoc(doc(db,'empresa_matriz_competencias',m.id));clearCache();toast('Treinamento excluído.');state.screen='trainings';state.activePlanId='';renderApp(true)}

function renderEmployees(d){const root=contentEl();root.innerHTML=`<section class="tr-section"><div class="tr-section-head"><div><h2>Funcionários</h2><p>Cadastro compartilhado por todos os treinamentos. Adicionar alguém novo não reinicia públicos já definidos.</p></div><div><button class="tr-btn soft" type="button" data-import>Importar do Apontamento</button> <button class="tr-btn gold" type="button" data-new-employee>Novo funcionário</button></div></div>${d.cols.length?`<div class="tr-table-wrap"><table class="tr-table"><thead><tr><th>Nome</th><th>Função</th><th>Setor</th><th>Admissão</th><th>Status</th><th></th></tr></thead><tbody>${d.cols.map(c=>`<tr><td><strong>${esc(c.nome||'')}</strong></td><td>${esc(c.funcao||'-')}</td><td>${esc(c.setor||'-')}</td><td>${dateBr(c.admissao)}</td><td>${badge(c.ativo===false?'Inativo':'Ativo')}</td><td><button class="tr-btn danger" data-delete-employee="${c.id}">Excluir</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="tr-empty"><strong>Nenhum funcionário cadastrado</strong>Importe do Apontamento ou cadastre manualmente.</div>`}</section>`;root.querySelector('[data-import]')?.addEventListener('click',importEmployees);root.querySelector('[data-new-employee]')?.addEventListener('click',showEmployeeForm);root.querySelectorAll('[data-delete-employee]').forEach(b=>b.addEventListener('click',()=>deleteEmployee(b.dataset.deleteEmployee,d)))}
function showEmployeeForm(){const bg=modal('Novo funcionário','Cadastre as informações essenciais.',`<form class="tr-form" data-employee-form><div><label>Nome *</label><input name="nome" required></div><div><label>Função</label><input name="funcao"></div><div><label>Setor</label><input name="setor"></div><div><label>Data de admissão</label><input type="date" name="admissao"></div><div class="full"><button class="tr-btn primary" type="submit">Salvar funcionário</button></div></form>`);bg.querySelector('[data-employee-form]').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await addDoc(collection(db,'empresa_colaboradores'),{empresaId:state.empresaId,nome:f.get('nome'),funcao:f.get('funcao')||'',setor:f.get('setor')||'',admissao:f.get('admissao')||'',ativo:true,criadoEm:serverTimestamp(),criadoPor:state.user?.uid||''});bg.remove();clearCache();toast('Funcionário cadastrado.');renderApp(true)})}
async function importEmployees(){const prod=await qCompany('empresa_funcionarios');const d=await loadData();const names=new Set(d.cols.map(x=>norm(x.nome)));let count=0;for(const f of prod){const nome=String(f.nome||'').trim();if(!nome||names.has(norm(nome)))continue;await addDoc(collection(db,'empresa_colaboradores'),{empresaId:state.empresaId,nome,funcao:f.funcao||'',setor:f.equipeNome||f.setor||'',ativo:f.ativo!==false,origemApontamentoId:f.id,criadoEm:serverTimestamp(),criadoPor:state.user?.uid||''});names.add(norm(nome));count++}clearCache();toast(count?`${count} funcionário(s) importado(s).`:'Nenhum funcionário novo para importar.');renderApp(true)}
async function deleteEmployee(id,d){if(!confirm('Excluir este funcionário da área de treinamentos?'))return;await deleteDoc(doc(db,'empresa_colaboradores',id));for(const m of d.matrix.filter(x=>x.colaboradorId===id))await deleteDoc(doc(db,'empresa_matriz_competencias',m.id));clearCache();toast('Funcionário excluído.');renderApp(true)}
async function saveMatrix(old,data){if(old?.id)await updateDoc(doc(db,'empresa_matriz_competencias',old.id),{...data,atualizadoEm:serverTimestamp(),atualizadoPor:state.user?.uid||''});else await addDoc(collection(db,'empresa_matriz_competencias'),{...data,criadoEm:serverTimestamp(),criadoPor:state.user?.uid||'',atualizadoEm:serverTimestamp()})}

function renderPlan(d){const root=contentEl();const plan=d.plans.find(p=>p.id===state.activePlanId);if(!plan){state.screen='trainings';return renderApp()};const st=planStage(plan,d);const labels={1:['Definir público','Escolha quem precisa fazer este treinamento.'],2:['Registrar realização','Registre quando este treinamento aconteceu e quem participou.'],3:['Avaliar eficácia','Confirme se o treinamento funcionou para cada participante.'],4:['Treinamento concluído','O processo deste treinamento está completo e já pode ser demonstrado em relatório.']};const steps=[];for(let i=1;i<=st.step;i++)steps.push(`<button type="button" class="${i===st.step?'active':''}">${i}. ${i===1?'Público':i===2?'Realização':i===3?'Eficácia':'Concluído'}</button>`);root.innerHTML=`<div class="tr-flow-head"><div class="tr-current"><div class="tr-current-num">${st.step===4?'✓':st.step}</div><div><h2>${esc(plan.titulo||'Treinamento')}</h2><p>${esc(labels[st.step][0])} — ${esc(labels[st.step][1])}</p></div></div><div class="tr-step-nav"><button type="button" data-back-cards>← Cards</button>${steps.join('')}</div></div><div data-plan-body></div>`;root.querySelector('[data-back-cards]')?.addEventListener('click',()=>{state.screen='trainings';state.activePlanId='';renderApp()});renderPlanStage(plan,d,st.step)}
function renderPlanStage(plan,d,step){const box=document.querySelector('[data-plan-body]');if(!box)return;if(step===1)return renderAudienceStage(plan,d,box);if(step===2)return renderRealizationStage(plan,d,box);if(step===3)return renderEfficacyStage(plan,d,box);return renderCompletedStage(plan,d,box)}

function renderAudienceStage(plan,d,box){const rows=planRows(plan,d);box.innerHTML=`<section class="tr-section"><div class="tr-section-head"><div><h2>1. Público</h2><p>Defina as pessoas obrigadas a fazer este treinamento.</p></div><button class="tr-btn gold" type="button" data-audience>Definir pessoas</button></div>${!d.cols.length?`<div class="tr-alert info"><strong>Nenhum funcionário cadastrado.</strong> Cadastre ou importe funcionários antes de definir o público. <button class="tr-btn soft" data-go-employees>Funcionários</button></div>`:rows.length?`<div class="tr-table-wrap"><table class="tr-table"><thead><tr><th>Funcionário</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.colaboradorNome)}</strong></td><td>${badge(r.status)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="tr-empty">Público ainda não definido.</div>'}</section>`;box.querySelector('[data-audience]')?.addEventListener('click',()=>{if(!d.cols.length){state.screen='employees';state.activePlanId='';return renderApp()}showAudience(plan,d)});box.querySelector('[data-go-employees]')?.addEventListener('click',()=>{state.screen='employees';state.activePlanId='';renderApp()})}
function showAudience(plan,d){const existing=d.matrix.filter(m=>m.treinamentoId===plan.id);const selected=new Set(existing.filter(m=>m.aplicavel!==false&&norm(m.status)!=='nao aplicavel').map(m=>m.colaboradorId));const people=d.cols.filter(c=>c.ativo!==false);const bg=modal('Quem precisa deste treinamento?',plan.titulo||'Treinamento',`<div class="tr-audience-tools"><label class="tr-audience-search"><input type="search" data-audience-search placeholder="Buscar por nome, função ou setor..." autocomplete="off"><span>⌕</span></label><div class="tr-audience-actions"><button class="tr-btn soft" type="button" data-select-visible>Selecionar visíveis</button><button class="tr-btn soft" type="button" data-clear-visible>Limpar visíveis</button></div></div><div class="tr-audience-meta"><span class="tr-badge warn" data-selected-count>0 selecionado(s)</span><span class="tr-badge" data-visible-count>0 exibido(s)</span><span class="tr-badge">${people.length} ativo(s)</span></div><div class="tr-people-list">${people.map(c=>`<label class="tr-person-card ${selected.has(c.id)?'selected':''}" data-person-card data-search="${esc(norm([c.nome,c.funcao,c.setor].filter(Boolean).join(' ')))}"><input type="checkbox" data-person value="${esc(c.id)}" ${selected.has(c.id)?'checked':''}><span class="tr-person-avatar">${esc(initials(c.nome))}</span><span class="tr-person-info"><strong>${esc(c.nome||'Funcionário')}</strong><small>${esc([c.funcao||'Sem função',c.setor||'Sem setor'].join(' • '))}</small></span></label>`).join('')||'<div class="tr-empty">Nenhum funcionário ativo cadastrado.</div>'}</div><div class="tr-audience-footer"><div><strong data-footer-selected>0 pessoa(s) selecionada(s)</strong><small>Somente as pessoas marcadas ficarão obrigadas a realizar este treinamento.</small></div><button class="tr-btn primary" type="button" data-save-audience>Salvar pessoas</button></div>`);const search=bg.querySelector('[data-audience-search]'),cards=[...bg.querySelectorAll('[data-person-card]')],checks=[...bg.querySelectorAll('[data-person]')],visible=()=>cards.filter(c=>!c.classList.contains('hidden'));const update=()=>{cards.forEach(c=>c.classList.toggle('selected',!!c.querySelector('[data-person]')?.checked));const sc=checks.filter(c=>c.checked).length;bg.querySelector('[data-selected-count]').textContent=`${sc} selecionado(s)`;bg.querySelector('[data-visible-count]').textContent=`${visible().length} exibido(s)`;bg.querySelector('[data-footer-selected]').textContent=`${sc} pessoa(s) selecionada(s)`};search?.addEventListener('input',()=>{const term=norm(search.value);cards.forEach(c=>c.classList.toggle('hidden',!!term&&!String(c.dataset.search||'').includes(term)));update()});checks.forEach(c=>c.addEventListener('change',update));bg.querySelector('[data-select-visible]')?.addEventListener('click',()=>{visible().forEach(card=>{const c=card.querySelector('[data-person]');if(c)c.checked=true});update()});bg.querySelector('[data-clear-visible]')?.addEventListener('click',()=>{visible().forEach(card=>{const c=card.querySelector('[data-person]');if(c)c.checked=false});update()});bg.querySelector('[data-save-audience]').addEventListener('click',async()=>{const ids=new Set(checks.filter(x=>x.checked).map(x=>x.value));if(!ids.size)return toast('Selecione pelo menos um funcionário para este treinamento.','err');const map=new Map(existing.map(x=>[x.colaboradorId,x]));for(const c of d.cols){const old=map.get(c.id),applicable=ids.has(c.id),keepDone=applicable&&norm(old?.status)==='concluido';await saveMatrix(old,{empresaId:state.empresaId,colaboradorId:c.id,colaboradorNome:c.nome||'',treinamentoId:plan.id,treinamentoNome:plan.titulo||'Treinamento',aplicavel:applicable,status:applicable?(keepDone?'Concluído':'Pendente'):'Não aplicável',eficaciaStatus:applicable?(old?.eficaciaStatus||'Pendente'):'Não aplicável'})}await updateDoc(doc(db,'empresa_treinamentos',plan.id),{publicoDefinido:true,publicoTotal:ids.size,publicoAtualizadoEm:serverTimestamp(),atualizadoEm:serverTimestamp()});bg.remove();clearCache();toast('Público salvo.');renderApp(true)});update();search?.focus()}

async function ensurePid({colaboradorId,colaboradorNome,treinamentoId,treinamentoNome,origemId,motivo}){const pids=await qCompany('empresa_pids');const dup=pids.find(p=>p.autoGerado===true&&p.colaboradorId===colaboradorId&&p.origemId===origemId&&!['concluido','fechado'].includes(norm(p.status)));if(dup)return dup.id;const x=await addDoc(collection(db,'empresa_pids'),{empresaId:state.empresaId,colaboradorId,colaboradorNome,treinamentoId,treinamentoNome,origem:`Treinamento: ${treinamentoNome} — ${motivo}`,origemTipo:'treinamento',origemId,autoGerado:true,status:'Em andamento',objetivo:`Desenvolver a competência relacionada ao treinamento ${treinamentoNome}.`,competencias:motivo,acoes:`Reforçar conteúdo, acompanhar aplicação prática e realizar novo treinamento quando necessário.`,criadoEm:serverTimestamp(),criadoPor:state.user?.uid||''});return x.id}
async function recalcPlan(planId){const matrix=await qCompany('empresa_matriz_competencias');const rows=matrix.filter(m=>m.treinamentoId===planId&&m.aplicavel!==false&&norm(m.status)!=='nao aplicavel');const allEffective=rows.length>0&&rows.every(m=>norm(m.status)==='concluido'&&norm(m.eficaciaStatus)==='eficaz');await updateDoc(doc(db,'empresa_treinamentos',planId),{status:allEffective?'Concluído':'Em andamento',atualizadoEm:serverTimestamp()})}

function renderRealizationStage(plan,d,box){const rows=planRows(plan,d),pending=rows.filter(r=>norm(r.status)!=='concluido'),events=d.events.filter(e=>e.treinamentoId===plan.id);box.innerHTML=`<section class="tr-section"><div class="tr-section-head"><div><h2>2. Realização</h2><p>Registre somente este treinamento. Os demais cards continuam independentes.</p></div><button class="tr-btn gold" type="button" data-new-event ${pending.length?'':'disabled'}>Registrar realização</button></div>${pending.length?`<div class="tr-alert"><strong>${pending.length} pessoa(s) pendente(s).</strong></div><div class="tr-grid">${pending.map(r=>`<article class="tr-card"><h3>${esc(r.colaboradorNome)}</h3><p>Aguardando realização.</p></article>`).join('')}</div>`:`<div class="tr-alert success"><strong>Todas as pessoas deste treinamento concluíram a realização.</strong></div>`}${events.length?`<div class="tr-section" style="margin-top:14px"><h3>Histórico</h3><div class="tr-table-wrap"><table class="tr-table"><thead><tr><th>Data</th><th>Participantes</th><th>Instrutor</th><th>Evidência</th></tr></thead><tbody>${events.map(e=>`<tr><td>${dateBr(e.data)}</td><td>${esc((e.participanteNomes||[]).join(', ')||'-')}</td><td>${esc(e.instrutor||'-')}</td><td>${e.evidenciaUrl?`<a href="${esc(e.evidenciaUrl)}" target="_blank" rel="noopener">Abrir</a>`:'-'}</td></tr>`).join('')}</tbody></table></div></div>`:''}</section>`;box.querySelector('[data-new-event]')?.addEventListener('click',()=>showEventForm(plan,d,pending))}
function showEventForm(plan,d,pending){const bg=modal('Registrar realização',plan.titulo||'Treinamento',`<form class="tr-form" data-event-form><div><label>Data *</label><input type="date" name="data" required></div><div><label>Instrutor</label><input name="instrutor" value="${esc(plan.instrutor||'')}"></div><div><label>Carga horária</label><input name="cargaHoraria" value="${esc(plan.cargaHoraria||'')}"></div><div class="full"><label>Participantes e resultado</label><div>${pending.map(r=>`<div class="tr-person-result"><input type="checkbox" data-attendee value="${r.colaboradorId}" data-name="${esc(r.colaboradorNome)}" checked><strong>${esc(r.colaboradorNome)}</strong><select data-result><option>Aprovado</option><option>Reprovado</option></select></div>`).join('')}</div></div><div><label>Evidência</label><input type="file" name="evidencia" accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png"></div><div class="full"><label>Observações</label><textarea name="observacoes"></textarea></div><div class="full"><button class="tr-btn primary" type="submit">Salvar realização</button></div></form>`);const form=bg.querySelector('[data-event-form]');form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form),attendees=[...form.querySelectorAll('[data-attendee]:checked')].map(ch=>({id:ch.value,nome:ch.dataset.name,resultado:ch.closest('.tr-person-result').querySelector('[data-result]').value}));if(!attendees.length)return toast('Marque pelo menos um participante.','err');let evidenciaUrl='',evidenciaPath='',evidenciaNome='';const file=form.elements.evidencia.files?.[0];if(file){evidenciaNome=file.name;evidenciaPath=`empresas/${state.empresaId}/treinamentos/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const rr=ref(storage,evidenciaPath);await uploadBytes(rr,file);evidenciaUrl=await getDownloadURL(rr)}const eventRef=await addDoc(collection(db,'empresa_treinamento_eventos'),{empresaId:state.empresaId,treinamentoId:plan.id,treinamentoNome:plan.titulo||'Treinamento',data:f.get('data'),instrutor:f.get('instrutor')||'',cargaHoraria:f.get('cargaHoraria')||'',participantes:attendees,participanteIds:attendees.map(x=>x.id),participanteNomes:attendees.map(x=>x.nome),resultado:attendees.every(x=>x.resultado==='Aprovado')?'Aprovado':'Misto',observacoes:f.get('observacoes')||'',evidenciaUrl,evidenciaPath,evidenciaNome,criadoEm:serverTimestamp(),criadoPor:state.user?.uid||''});for(const a of attendees){const row=d.matrix.find(m=>m.treinamentoId===plan.id&&m.colaboradorId===a.id);if(!row)continue;if(a.resultado==='Aprovado')await updateDoc(doc(db,'empresa_matriz_competencias',row.id),{status:'Concluído',eficaciaStatus:'Pendente',ultimaRealizacaoId:eventRef.id,ultimaRealizacaoData:f.get('data'),atualizadoEm:serverTimestamp()});else{await updateDoc(doc(db,'empresa_matriz_competencias',row.id),{status:'Pendente',eficaciaStatus:'Ineficaz',ultimaRealizacaoId:eventRef.id,ultimaRealizacaoData:f.get('data'),atualizadoEm:serverTimestamp()});await ensurePid({colaboradorId:a.id,colaboradorNome:a.nome,treinamentoId:plan.id,treinamentoNome:plan.titulo||'Treinamento',origemId:`${eventRef.id}:${a.id}`,motivo:'Resultado reprovado no treinamento.'})}}await updateDoc(doc(db,'empresa_treinamentos',plan.id),{status:'Em andamento',ultimaRealizacaoData:f.get('data'),atualizadoEm:serverTimestamp()});bg.remove();clearCache();toast('Realização registrada.');renderApp(true)})}

function renderEfficacyStage(plan,d,box){const rows=planRows(plan,d),pending=rows.filter(r=>norm(r.status)==='concluido'&&norm(r.eficaciaStatus)!=='eficaz');box.innerHTML=`<section class="tr-section"><div class="tr-section-head"><div><h2>3. Eficácia</h2><p>Valide o resultado deste treinamento.</p></div></div>${pending.length?`<div class="tr-grid">${pending.map(r=>`<article class="tr-card"><h3>${esc(r.colaboradorNome)}</h3><p>Realização: ${dateBr(r.ultimaRealizacaoData)}</p><div class="tr-card-foot"><span class="tr-badge warn">Aguardando eficácia</span><button class="tr-btn gold" data-efficacy="${r.id}">Avaliar</button></div></article>`).join('')}</div>`:`<div class="tr-alert success"><strong>Todas as eficácias deste treinamento foram validadas.</strong></div>`}</section>`;box.querySelectorAll('[data-efficacy]').forEach(b=>b.addEventListener('click',()=>showEfficacy(plan,d.matrix.find(m=>m.id===b.dataset.efficacy))))}
function showEfficacy(plan,row){const bg=modal('Avaliar eficácia',`${row.colaboradorNome} • ${plan.titulo||'Treinamento'}`,`<form class="tr-form" data-efficacy-form><div><label>Resultado *</label><select name="resultado" required><option>Eficaz</option><option>Ineficaz</option></select></div><div><label>Data</label><input type="date" name="data"></div><div><label>Avaliador</label><input name="avaliador"></div><div class="full"><label>Observações</label><textarea name="observacoes"></textarea></div><div class="full"><button class="tr-btn primary" type="submit">Salvar avaliação</button></div></form>`);bg.querySelector('[data-efficacy-form]').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),result=f.get('resultado');if(result==='Eficaz')await updateDoc(doc(db,'empresa_matriz_competencias',row.id),{status:'Concluído',eficaciaStatus:'Eficaz',eficaciaData:f.get('data')||'',eficaciaAvaliador:f.get('avaliador')||'',eficaciaObservacoes:f.get('observacoes')||'',atualizadoEm:serverTimestamp()});else{await updateDoc(doc(db,'empresa_matriz_competencias',row.id),{status:'Pendente',eficaciaStatus:'Ineficaz',eficaciaData:f.get('data')||'',eficaciaAvaliador:f.get('avaliador')||'',eficaciaObservacoes:f.get('observacoes')||'',atualizadoEm:serverTimestamp()});await ensurePid({colaboradorId:row.colaboradorId,colaboradorNome:row.colaboradorNome,treinamentoId:row.treinamentoId,treinamentoNome:row.treinamentoNome,origemId:`eficacia:${row.id}:${f.get('data')||Date.now()}`,motivo:'Treinamento avaliado como ineficaz.'})}await recalcPlan(plan.id);bg.remove();clearCache();toast(result==='Eficaz'?'Eficácia confirmada.':'Ineficácia registrada. Um PID foi aberto e este treinamento voltou para realização.');renderApp(true)})}
function renderCompletedStage(plan,d,box){const rows=planRows(plan,d),events=d.events.filter(e=>e.treinamentoId===plan.id);box.innerHTML=`<div class="tr-alert success"><strong>Treinamento concluído.</strong> Todo o público obrigatório concluiu a realização e teve eficácia validada.</div><div class="tr-summary"><div class="tr-kpi"><small>Público</small><strong>${rows.length}</strong></div><div class="tr-kpi"><small>Concluídos</small><strong>${rows.filter(r=>norm(r.status)==='concluido').length}</strong></div><div class="tr-kpi"><small>Eficazes</small><strong>${rows.filter(r=>norm(r.eficaciaStatus)==='eficaz').length}</strong></div><div class="tr-kpi"><small>Evidências</small><strong>${events.filter(e=>e.evidenciaUrl).length}</strong></div></div><section class="tr-section" style="margin-top:14px"><div class="tr-section-head"><div><h2>Resultado deste treinamento</h2><p>Gere o relatório completo na aba de relatórios.</p></div><button class="tr-btn primary" data-report-plan>Gerar relatório</button></div></section>`;box.querySelector('[data-report-plan]')?.addEventListener('click',()=>{state.screen='reports';state.activePlanId='';state.reportFilters.trainingId=plan.id;state.reportFilters.type='treinamento';state.reportReady=true;renderApp()})}

function inRange(v,from,to){if(!from&&!to)return true;if(!v)return false;const s=String(v).slice(0,10);if(from&&s<from)return false;if(to&&s>to)return false;return true}
function isLate(row,d){const p=d.plans.find(x=>x.id===row.treinamentoId);return !!p?.dataPrevista&&String(p.dataPrevista).slice(0,10)<new Date().toISOString().slice(0,10)&&norm(row.status)!=='concluido'}
function reportData(d){const f=state.reportFilters,employeeMap=new Map(d.cols.map(c=>[c.id,c])),planMap=new Map(d.plans.map(p=>[p.id,p]));const rows=applicableRows(d).filter(m=>{const c=employeeMap.get(m.colaboradorId),p=planMap.get(m.treinamentoId);if(f.trainingId&&m.treinamentoId!==f.trainingId)return false;if(f.employeeId&&m.colaboradorId!==f.employeeId)return false;if(f.sector&&norm(c?.setor)!==norm(f.sector))return false;const date=m.ultimaRealizacaoData||p?.dataPrevista||'';if(!inRange(date,f.from,f.to))return false;if(f.status==='pendente'&&norm(m.status)==='concluido')return false;if(f.status==='concluido'&&norm(m.status)!=='concluido')return false;if(f.status==='eficaz'&&norm(m.eficaciaStatus)!=='eficaz')return false;if(f.status==='ineficaz'&&norm(m.eficaciaStatus)!=='ineficaz')return false;if(f.status==='atrasado'&&!isLate(m,d))return false;return true});const events=d.events.filter(e=>{if(f.trainingId&&e.treinamentoId!==f.trainingId)return false;if(f.employeeId&&!(e.participanteIds||[]).includes(f.employeeId))return false;if(!inRange(e.data,f.from,f.to))return false;if(f.sector){const ids=new Set(d.cols.filter(c=>norm(c.setor)===norm(f.sector)).map(c=>c.id));if(!(e.participanteIds||[]).some(id=>ids.has(id)))return false}return true});const plans=d.plans.filter(p=>!f.trainingId||p.id===f.trainingId);const employees=d.cols.filter(c=>(!f.employeeId||c.id===f.employeeId)&&(!f.sector||norm(c.setor)===norm(f.sector)));return{rows,events,plans,employees,employeeMap,planMap}}
function reportHeader(title,sub=''){return `<div class="tr-report-title"><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div><span class="tr-badge">${new Date().toLocaleString('pt-BR')}</span></div>`}
function reportKpis(d,r){const completed=r.rows.filter(x=>norm(x.status)==='concluido').length,effective=r.rows.filter(x=>norm(x.eficaciaStatus)==='eficaz').length,late=r.rows.filter(x=>isLate(x,d)).length,evidences=r.events.filter(e=>e.evidenciaUrl).length;return `<div class="tr-report-kpis"><div class="tr-report-kpi"><small>Treinamentos</small><strong>${r.plans.length}</strong></div><div class="tr-report-kpi"><small>Competências</small><strong>${r.rows.length}</strong></div><div class="tr-report-kpi"><small>Concluídas</small><strong>${completed}</strong></div><div class="tr-report-kpi"><small>Eficazes</small><strong>${effective}</strong></div><div class="tr-report-kpi"><small>Evidências</small><strong>${evidences}</strong></div></div><div class="tr-report-note">Conclusão: ${pct(completed,r.rows.length)} • Eficácia: ${pct(effective,r.rows.length)} • Atrasadas: ${late}</div>`}
function reportGeneral(d,r){return `${reportHeader('Relatório geral de treinamentos',state.empresaNome)}${reportKpis(d,r)}<div class="tr-report-block"><h3>Resumo por treinamento</h3><div class="tr-table-wrap"><table class="tr-table"><thead><tr><th>Treinamento</th><th>Etapa</th><th>Previsão</th><th>Obrigatórios</th><th>Concluídos</th><th>Eficazes</th><th>Pendentes</th></tr></thead><tbody>${r.plans.map(p=>{const rows=r.rows.filter(x=>x.treinamentoId===p.id),st=planStage(p,d);return `<tr><td><strong>${esc(p.titulo||'Treinamento')}</strong></td><td><span class="tr-badge ${st.cls}">${esc(st.label)}</span></td><td>${dateBr(p.dataPrevista)}</td><td>${rows.length}</td><td>${rows.filter(x=>norm(x.status)==='concluido').length}</td><td>${rows.filter(x=>norm(x.eficaciaStatus)==='eficaz').length}</td><td>${rows.filter(x=>norm(x.status)!=='concluido').length}</td></tr>`}).join('')||'<tr><td colspan="7">Sem dados.</td></tr>'}</tbody></table></div></div>`}
function reportTraining(d,r){return `${reportHeader('Relatório do treinamento',state.empresaNome)}${r.plans.map(p=>{const rows=r.rows.filter(x=>x.treinamentoId===p.id),events=r.events.filter(e=>e.treinamentoId===p.id),st=planStage(p,d);return `<div class="tr-report-block"><h3>${esc(p.titulo||'Treinamento')}</h3><div class="tr-report-note">Etapa: ${esc(st.label)} • Previsão: ${dateBr(p.dataPrevista)} • Instrutor: ${esc(p.instrutor||'-')} • Carga: ${esc(p.cargaHoraria||'-')} • Público: ${rows.length}</div><div class="tr-table-wrap"><table class="tr-table"><thead><tr><th>Funcionário</th><th>Função/Setor</th><th>Status</th><th>Realização</th><th>Eficácia</th><th>Avaliador</th></tr></thead><tbody>${rows.map(x=>{const c=r.employeeMap.get(x.colaboradorId);return `<tr><td><strong>${esc(x.colaboradorNome)}</strong></td><td>${esc([c?.funcao,c?.setor].filter(Boolean).join(' • ')||'-')}</td><td>${badge(x.status)}</td><td>${dateBr(x.ultimaRealizacaoData)}</td><td>${badge(x.eficaciaStatus)}</td><td>${esc(x.eficaciaAvaliador||'-')}</td></tr>`}).join('')||'<tr><td colspan="6">Público ainda não definido.</td></tr>'}</tbody></table></div>${events.filter(e=>e.evidenciaUrl).length?`<div class="tr-report-note">Evidências: ${events.filter(e=>e.evidenciaUrl).map(e=>esc(e.evidenciaNome||'arquivo')).join(', ')}</div>`:''}</div>`}).join('')||'<div class="tr-empty">Selecione um treinamento.</div>'}`}
function reportEmployee(d,r){return `${reportHeader('Dossiê por funcionário',state.empresaNome)}${r.employees.map(c=>{const rows=r.rows.filter(x=>x.colaboradorId===c.id);return `<div class="tr-report-block"><h3>${esc(c.nome)}</h3><div class="tr-report-note">${esc(c.funcao||'-')} • ${esc(c.setor||'-')} • Admissão: ${dateBr(c.admissao)}</div><div class="tr-table-wrap"><table class="tr-table"><thead><tr><th>Treinamento</th><th>Status</th><th>Realização</th><th>Eficácia</th><th>Avaliador</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.treinamentoNome)}</strong></td><td>${badge(x.status)}</td><td>${dateBr(x.ultimaRealizacaoData)}</td><td>${badge(x.eficaciaStatus)}</td><td>${esc(x.eficaciaAvaliador||'-')}</td></tr>`).join('')||'<tr><td colspan="5">Sem treinamentos.</td></tr>'}</tbody></table></div></div>`}).join('')||'<div class="tr-empty">Sem funcionário no filtro.</div>'}`}
function reportMatrix(d,r){const plans=r.plans,employees=r.employees;return `${reportHeader('Matriz de competências',state.empresaNome)}<div class="tr-table-wrap"><table class="tr-table"><thead><tr><th>Funcionário</th>${plans.map(p=>`<th>${esc(p.titulo||'Treinamento')}</th>`).join('')}</tr></thead><tbody>${employees.map(c=>`<tr><td><strong>${esc(c.nome)}</strong><br><small>${esc(c.setor||'')}</small></td>${plans.map(p=>{const x=d.matrix.find(m=>m.colaboradorId===c.id&&m.treinamentoId===p.id);if(!x||x.aplicavel===false||norm(x.status)==='nao aplicavel')return '<td>—</td>';return `<td>${badge(x.status)}<br>${norm(x.status)==='concluido'?badge(x.eficaciaStatus):''}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
function reportPending(d,r){const rows=r.rows.filter(x=>norm(x.status)!=='concluido'||norm(x.eficaciaStatus)!=='eficaz');return `${reportHeader('Pendências e atrasados',state.empresaNome)}<div class="tr-table-wrap"><table class="tr-table"><thead><tr><th>Funcionário</th><th>Treinamento</th><th>Previsão</th><th>Status</th><th>Eficácia</th><th>Situação</th></tr></thead><tbody>${rows.map(x=>{const p=r.planMap.get(x.treinamentoId);return `<tr><td><strong>${esc(x.colaboradorNome)}</strong></td><td>${esc(x.treinamentoNome)}</td><td>${dateBr(p?.dataPrevista)}</td><td>${badge(x.status)}</td><td>${badge(x.eficaciaStatus)}</td><td>${isLate(x,d)?'<span class="tr-badge bad">Atrasado</span>':'<span class="tr-badge warn">Pendente</span>'}</td></tr>`}).join('')||'<tr><td colspan="6">Nenhuma pendência no filtro.</td></tr>'}</tbody></table></div>`}
function reportEfficacy(d,r){return `${reportHeader('Relatório de eficácia',state.empresaNome)}<div class="tr-table-wrap"><table class="tr-table"><thead><tr><th>Funcionário</th><th>Treinamento</th><th>Realização</th><th>Resultado</th><th>Data avaliação</th><th>Avaliador</th><th>Observações</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td><strong>${esc(x.colaboradorNome)}</strong></td><td>${esc(x.treinamentoNome)}</td><td>${dateBr(x.ultimaRealizacaoData)}</td><td>${badge(x.eficaciaStatus)}</td><td>${dateBr(x.eficaciaData)}</td><td>${esc(x.eficaciaAvaliador||'-')}</td><td>${esc(x.eficaciaObservacoes||'-')}</td></tr>`).join('')||'<tr><td colspan="7">Sem dados de eficácia.</td></tr>'}</tbody></table></div>`}
function reportEvidence(d,r){const ev=r.events.filter(e=>e.evidenciaUrl);return `${reportHeader('Evidências de treinamentos',state.empresaNome)}<div class="tr-evidence-list">${ev.map(e=>`<div class="tr-evidence"><div><strong>${esc(e.treinamentoNome||'Treinamento')}</strong><small>${dateBr(e.data)} • ${esc((e.participanteNomes||[]).join(', ')||'-')} • ${esc(e.evidenciaNome||'Arquivo')}</small></div><a class="tr-btn soft" href="${esc(e.evidenciaUrl)}" target="_blank" rel="noopener">Abrir evidência</a></div>`).join('')||'<div class="tr-empty">Nenhuma evidência anexada.</div>'}</div>`}
function reportAudit(d,r){const openPids=d.pids.filter(p=>!['concluido','fechado'].includes(norm(p.status)));return `<div class="tr-audit-cover"><h2>Dossiê de auditoria — Treinamentos e Competências</h2><p>${esc(state.empresaNome)} • Gerado em ${new Date().toLocaleString('pt-BR')}</p></div>${reportKpis(d,r)}<div class="tr-report-block"><h3>1. Plano e situação</h3>${reportGeneral(d,r).replace(reportHeader('Relatório geral de treinamentos',state.empresaNome),'')}</div><div class="tr-report-block"><h3>2. Matriz de competências</h3>${reportMatrix(d,r).replace(reportHeader('Matriz de competências',state.empresaNome),'')}</div><div class="tr-report-block"><h3>3. Evidências</h3>${reportEvidence(d,r).replace(reportHeader('Evidências de treinamentos',state.empresaNome),'')}</div><div class="tr-report-block"><h3>4. Eficácia</h3>${reportEfficacy(d,r).replace(reportHeader('Relatório de eficácia',state.empresaNome),'')}</div><div class="tr-report-block"><h3>5. PIDs</h3><div class="tr-table-wrap"><table class="tr-table"><thead><tr><th>Funcionário</th><th>Origem</th><th>Status</th><th>Prazo</th><th>Objetivo</th></tr></thead><tbody>${d.pids.map(x=>`<tr><td>${esc(x.colaboradorNome||'-')}</td><td>${esc(x.origem||'-')}</td><td>${badge(x.status||'Em andamento')}</td><td>${dateBr(x.prazo)}</td><td>${esc(x.objetivo||'-')}</td></tr>`).join('')||'<tr><td colspan="5">Sem PID.</td></tr>'}</tbody></table></div><div class="tr-report-note">PID(s) abertos: ${openPids.length}</div></div>`}
function buildReport(d){const r=reportData(d),t=state.reportFilters.type;return t==='treinamento'?reportTraining(d,r):t==='funcionario'?reportEmployee(d,r):t==='matriz'?reportMatrix(d,r):t==='pendencias'?reportPending(d,r):t==='eficacia'?reportEfficacy(d,r):t==='evidencias'?reportEvidence(d,r):t==='auditoria'?reportAudit(d,r):reportGeneral(d,r)}

function renderReports(d){const root=contentEl(),f=state.reportFilters,sectors=[...new Set(d.cols.map(c=>c.setor).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));root.innerHTML=`<section class="tr-section"><div class="tr-section-head"><div><h2>Relatórios gerais</h2><p>Escolha um treinamento específico ou deixe “Todos” para consolidar a empresa.</p></div></div><div class="tr-report-controls"><label>Treinamento<select data-r-training><option value="">Todos os treinamentos</option>${d.plans.map(p=>`<option value="${p.id}" ${f.trainingId===p.id?'selected':''}>${esc(p.titulo||'Treinamento')} — ${esc(planStage(p,d).label)}</option>`).join('')}</select></label><label>Tipo de relatório<select data-r-type>${Object.entries(REPORT_LABELS).map(([id,label])=>`<option value="${id}" ${f.type===id?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label>De<input type="date" data-r-from value="${esc(f.from)}"></label><label>Até<input type="date" data-r-to value="${esc(f.to)}"></label><button class="tr-btn primary" data-r-generate>Gerar relatório</button></div><details><summary style="cursor:pointer;font-weight:850;color:#073F5A;margin-bottom:10px">Filtros adicionais</summary><div class="tr-report-advanced"><label>Funcionário<select data-r-employee><option value="">Todos</option>${d.cols.map(c=>`<option value="${c.id}" ${f.employeeId===c.id?'selected':''}>${esc(c.nome)}</option>`).join('')}</select></label><label>Setor<select data-r-sector><option value="">Todos</option>${sectors.map(s=>`<option value="${esc(s)}" ${f.sector===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Status<select data-r-status><option value="">Todos</option><option value="pendente" ${f.status==='pendente'?'selected':''}>Pendente</option><option value="concluido" ${f.status==='concluido'?'selected':''}>Concluído</option><option value="eficaz" ${f.status==='eficaz'?'selected':''}>Eficaz</option><option value="ineficaz" ${f.status==='ineficaz'?'selected':''}>Ineficaz</option><option value="atrasado" ${f.status==='atrasado'?'selected':''}>Atrasado</option></select></label></div></details>${state.reportReady?`<div class="tr-report-actions"><button class="tr-btn soft" data-r-clear>Limpar filtros</button><button class="tr-btn primary" data-r-print>Imprimir / Salvar PDF</button></div><div class="tr-report-preview" data-report-preview>${buildReport(d)}</div>`:`<div class="tr-empty"><strong>Escolha o treinamento e gere o relatório</strong>Você pode gerar um relatório individual ou consolidar todos os treinamentos.</div>`}</section>`;const sync=()=>{state.reportFilters.trainingId=root.querySelector('[data-r-training]')?.value||'';state.reportFilters.type=root.querySelector('[data-r-type]')?.value||'geral';state.reportFilters.from=root.querySelector('[data-r-from]')?.value||'';state.reportFilters.to=root.querySelector('[data-r-to]')?.value||'';state.reportFilters.employeeId=root.querySelector('[data-r-employee]')?.value||'';state.reportFilters.sector=root.querySelector('[data-r-sector]')?.value||'';state.reportFilters.status=root.querySelector('[data-r-status]')?.value||''};root.querySelector('[data-r-generate]')?.addEventListener('click',()=>{sync();state.reportReady=true;renderReports(d)});root.querySelector('[data-r-clear]')?.addEventListener('click',()=>{state.reportFilters={type:'geral',from:'',to:'',trainingId:'',employeeId:'',sector:'',status:''};state.reportReady=false;renderReports(d)});root.querySelector('[data-r-print]')?.addEventListener('click',printCurrentReport)}
function printCurrentReport(){const preview=document.querySelector('[data-report-preview]');if(!preview)return;const frame=document.createElement('iframe');frame.style.cssText='position:fixed;right:0;bottom:0;width:0;height:0;border:0';document.body.appendChild(frame);const w=frame.contentWindow,d=frame.contentDocument;d.open();d.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(REPORT_LABELS[state.reportFilters.type]||'Relatório')}</title><style>@page{size:A4 landscape;margin:8mm}body{font-family:Arial,sans-serif;color:#173846;font-size:10px}h2,h3{color:#073F5A;margin:8px 0}.tr-report-title{display:flex;justify-content:space-between;border-bottom:2px solid #073F5A;padding-bottom:6px;margin-bottom:8px}.tr-report-title p{margin:2px 0}.tr-badge{display:inline-block;border:1px solid #b7cbd3;border-radius:10px;padding:2px 5px;font-size:8px}.tr-report-kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;margin:7px 0}.tr-report-kpi{border:1px solid #cfdfe5;padding:6px;border-radius:6px}.tr-report-kpi small{display:block}.tr-report-kpi strong{font-size:16px;color:#073F5A}.tr-table{width:100%;border-collapse:collapse}.tr-table th,.tr-table td{border:1px solid #d7e2e6;padding:4px;text-align:left;vertical-align:top}.tr-table th{background:#eef4f6;font-size:8px}.tr-report-block{margin-top:9px}.tr-evidence{border:1px solid #d7e2e6;padding:5px;margin:4px 0}.tr-btn{display:none}.tr-audit-cover{border:2px solid #073F5A;padding:10px;margin-bottom:8px}.tr-report-note{font-size:8px;color:#546c76}</style></head><body><div style="font-weight:bold;font-size:15px;color:#073F5A">Excellence System®</div><div>${esc(state.empresaNome)}</div>${preview.innerHTML}<div style="margin-top:12px;border-top:1px solid #aaa;padding-top:5px;font-size:8px">Relatório gerado automaticamente pelo Excellence System® • ${new Date().toLocaleString('pt-BR')}</div></body></html>`);d.close();setTimeout(()=>{w.focus();w.print();setTimeout(()=>frame.remove(),1000)},250)}

function renderManagement(d){const root=contentEl();root.innerHTML=`<section class="tr-section"><div class="tr-section-head"><div><h2>Gestão contínua</h2><p>Integração, PID e carreira ficam separados do fluxo dos cards de treinamento.</p></div></div><div class="tr-aux-grid"><div class="tr-aux"><h3>Integração</h3><p>${d.integrations.length} registro(s).</p><button class="tr-btn soft" data-aux="integracao">Abrir integração</button></div><div class="tr-aux"><h3>PID</h3><p>${d.pids.filter(p=>!['concluido','fechado'].includes(norm(p.status))).length} aberto(s).</p><button class="tr-btn gold" data-aux="pid">Abrir PID</button></div><div class="tr-aux"><h3>Carreira</h3><p>${d.careers.length} registro(s).</p><button class="tr-btn soft" data-aux="carreira">Abrir carreira</button></div></div></section>`;root.querySelectorAll('[data-aux]').forEach(b=>b.addEventListener('click',()=>renderAux(b.dataset.aux)))}
async function renderAux(type){const main=mainEl();if(!main)return;const map={integracao:['Integração','empresa_integracoes'],pid:['PID','empresa_pids'],carreira:['Carreira','empresa_carreiras']};const [title,col]=map[type],rows=await qCompany(col);main.innerHTML=`<section class="tr-root"><div class="tr-hero"><div><small>GESTÃO CONTÍNUA</small><h1>${title}</h1><p>${esc(state.empresaNome)}</p></div><div class="tr-hero-actions"><button class="tr-btn soft" data-back-management>Voltar</button></div></div><section class="tr-section" style="margin-top:16px"><div class="tr-section-head"><div><h2>${title}</h2><p>Área complementar do desenvolvimento profissional.</p></div><button class="tr-btn gold" data-new-aux>Novo registro</button></div>${rows.length?`<div class="tr-table-wrap"><table class="tr-table"><thead><tr><th>Funcionário</th><th>Resumo</th><th>Status</th><th>Data/Prazo</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.colaboradorNome||'-')}</strong></td><td>${esc(r.objetivo||r.origem||r.resultado30||r.cargoObjetivo||'-')}</td><td>${badge(r.status||'Em andamento')}</td><td>${dateBr(r.prazo||r.dataAvaliacao30||r.data||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="tr-empty">Nenhum registro.</div>'}</section></section>`;main.querySelector('[data-back-management]')?.addEventListener('click',()=>{state.screen='management';renderApp(true)});main.querySelector('[data-new-aux]')?.addEventListener('click',()=>showAuxForm(type))}
async function showAuxForm(type){const d=await loadData();let fields='';if(type==='integracao')fields=`<div><label>Data de admissão</label><input type="date" name="data"></div><div><label>Avaliação 30 dias</label><input type="date" name="dataAvaliacao30"></div><div><label>Institucional</label><select name="institucional"><option>Pendente</option><option>Concluído</option></select></div><div><label>SGQ</label><select name="sgq"><option>Pendente</option><option>Concluído</option></select></div><div><label>Técnica</label><select name="tecnica"><option>Pendente</option><option>Concluído</option></select></div><div><label>Liberação gestor</label><select name="gestor"><option>Pendente</option><option>Concluído</option></select></div><div class="full"><label>Resultado 30 dias</label><textarea name="resultado30"></textarea></div>`;if(type==='pid')fields=`<div><label>Origem</label><input name="origem"></div><div><label>Prazo</label><input type="date" name="prazo"></div><div class="full"><label>Objetivo</label><textarea name="objetivo"></textarea></div><div class="full"><label>Competências/lacunas</label><textarea name="competencias"></textarea></div><div class="full"><label>Ações</label><textarea name="acoes"></textarea></div>`;if(type==='carreira')fields=`<div><label>Cargo atual</label><input name="cargoAtual"></div><div><label>Objetivo futuro</label><input name="cargoObjetivo"></div><div><label>Nível atual (1 a 4)</label><input type="number" min="1" max="4" name="nivelAtual"></div><div><label>Nível esperado (1 a 4)</label><input type="number" min="1" max="4" name="nivelEsperado"></div><div class="full"><label>Lacunas</label><textarea name="lacunas"></textarea></div><div class="full"><label>Plano de ação</label><textarea name="acoes"></textarea></div>`;const bg=modal(type==='integracao'?'Nova integração':type==='pid'?'Novo PID':'Carreira e evolução','',`<form class="tr-form" data-aux-form><div><label>Funcionário *</label><select name="colaboradorId" required><option value="">Selecione</option>${d.cols.map(c=>`<option value="${c.id}">${esc(c.nome)}</option>`).join('')}</select></div><div><label>Status</label><select name="status"><option>Em andamento</option><option>Pendente</option><option>Concluído</option></select></div>${fields}<div class="full"><button class="tr-btn primary" type="submit">Salvar</button></div></form>`);bg.querySelector('[data-aux-form]').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),sel=e.currentTarget.elements.colaboradorId,col=type==='integracao'?'empresa_integracoes':type==='pid'?'empresa_pids':'empresa_carreiras',data={empresaId:state.empresaId,colaboradorId:f.get('colaboradorId'),colaboradorNome:sel.selectedOptions[0]?.textContent||'',status:f.get('status')||'Em andamento',criadoEm:serverTimestamp(),criadoPor:state.user?.uid||''};for(const[k,v]of f.entries())if(!['colaboradorId','status'].includes(k))data[k]=v;await addDoc(collection(db,col),data);bg.remove();clearCache();toast('Registro salvo.');renderAux(type)})}

window.__EXCELLENCE_TRAINING_OPEN=openTraining;
window.addEventListener('excellence-open-trainings',()=>openTraining());
document.addEventListener('excellence-open-trainings',()=>openTraining());
function startObserver(){if(state.observerStarted)return;state.observerStarted=true;new MutationObserver(()=>ensureMenu()).observe(document.body,{childList:true,subtree:true})}
onAuthStateChanged(auth,async user=>{try{await loadProfile(user);state.empresas=[];rememberCompany('','');state.screen='trainings';state.activePlanId='';clearCache();startObserver();ensureMenu()}catch(e){console.warn('Treinamentos:',e)}});
window.addEventListener('load',()=>{injectStyle();startObserver();ensureMenu()});
console.info(`Excellence System® Treinamentos raiz ${VERSION} carregado.`);
